(async()=>{const status=document.getElementById('offline-status'),update=document.getElementById('check-update');if(!status)return;
if(location.protocol==='file:'){status.textContent='本機檔案模式：程式與資料位於本機；手機安裝需HTTPS網址。';update.hidden=true;return}
if(!('serviceWorker'in navigator)||!window.isSecureContext){status.textContent='此環境不支援離線安裝，請使用HTTPS或本機localhost。';update.hidden=true;return}
let pending=false;const onUpdate=()=>{status.textContent='新版已下載。套用會清除本次輸入，請先完成手邊查詢。';update.textContent='套用新版並重新開啟';pending=true};
try{const reg=await navigator.serviceWorker.register('./sw.js');if(reg.waiting)onUpdate();reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)onUpdate()})});navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='OFFLINE_STATUS'&&!pending)status.textContent=e.data.ready?'本版本檔案已備妥離線使用。請在手機以飛航模式實測；瀏覽器清除資料後需重新下載。':'離線檔案尚未完整，請保持連線重新開啟。'});let reloadRequested=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloadRequested){location.reload();return}navigator.serviceWorker.controller?.postMessage({type:'STATUS'})});const ready=await navigator.serviceWorker.ready;(navigator.serviceWorker.controller||ready.active)?.postMessage({type:'STATUS'});update.onclick=async()=>{if(pending&&reg.waiting){reloadRequested=true;reg.waiting.postMessage({type:'ACTIVATE'});return}try{await reg.update();if(reg.waiting)onUpdate();else{status.textContent='已送出版本檢查；若有新版會顯示套用按鈕。';navigator.serviceWorker.controller?.postMessage({type:'STATUS'})}}catch{status.textContent='目前無法連線檢查；已快取版本仍可使用。'}}}catch{status.textContent='離線準備未成功，請勿假設已能離線使用。'}
})();
